const items = $input.all();

let output = [];

// ✅ CATEGORY MASTER (Sheet2 embedded)
const CATEGORY_MASTER = [
  { vendor: "amazon", name: "fbanweighthandlingshipping", ledger: "FBA Weight Handling Shipping Fee" },
  { vendor: "amazon", name: "fixedclosing", ledger: "Fixed Closing Fee" },
  { vendor: "amazon", name: "listing", ledger: "Listing Fee" },
  { vendor: "amazon", name: "ordercancellation", ledger: "Order Cancellation Fee" },
  { vendor: "amazon", name: "refundprocessing", ledger: "Refund Processing Fee" },
  { vendor: "amazon", name: "removal", ledger: "Removal Fee" },
  { vendor: "amazon", name: "shippingchargeback", ledger: "Shipping Chargeback Fee" }
];

// ✅ NORMALIZER
function normalize(text) {
  if (!text) return "";
  return text.toLowerCase()
    .replace(/private limited|pvt ltd|pvt\. ltd\.|limited|ltd/g, "")
    .replace(/amazon|blinkit/g, "")
    .replace(/fee|fees|charges|charge/g, "")
    .replace(/[^a-z]/g, "")
    .trim();
}

// ✅ GET VENDOR KEY
function getVendorKey(vendor) {
  const v = (vendor || "").toLowerCase();
  if (v.includes("amazon")) return "amazon";
  if (v.includes("blink")) return "blinkit";
  return "";
}

// ✅ CATEGORY MATCH
function getCategory(vendor, product) {
  const vendorKey = getVendorKey(vendor);
  const productNorm = normalize(product);

  let bestScore = 0;
  let bestMatch = "N/A";

  for (const row of CATEGORY_MASTER) {
    if (row.vendor !== vendorKey) continue;

    const nameNorm = row.name;

    let score = 0;

    if (productNorm.includes(nameNorm)) score = 100;
    else if (nameNorm.includes(productNorm)) score = 90;
    else {
      const words = nameNorm.match(/.{1,6}/g) || [];
      let match = 0;
      for (let w of words) {
        if (productNorm.includes(w)) match++;
      }
      score = (match / words.length) * 100;
    }

    if (score > bestScore) {
      bestScore = score;
      bestMatch = row.ledger;
    }
  }

  return bestScore >= 70 ? bestMatch : "N/A";
}

// ✅ GST STATE MAP
const GST_STATE_MAP = {
  '01': 'Jammu & Kashmir','02': 'Himachal Pradesh','03': 'Punjab','04': 'Chandigarh',
  '05': 'Uttarakhand','06': 'Haryana','07': 'Delhi','08': 'Rajasthan',
  '09': 'Uttar Pradesh','10': 'Bihar','11': 'Sikkim','12': 'Arunachal Pradesh',
  '13': 'Nagaland','14': 'Manipur','15': 'Mizoram','16': 'Tripura',
  '17': 'Meghalaya','18': 'Assam','19': 'West Bengal','20': 'Jharkhand',
  '21': 'Odisha','22': 'Chhattisgarh','23': 'Madhya Pradesh','24': 'Gujarat',
  '25': 'Dadra & Nagar Haveli and Daman & Diu','26': 'Dadra & Nagar Haveli and Daman & Diu',
  '27': 'Maharashtra','28': 'Andhra Pradesh','29': 'Karnataka','30': 'Goa',
  '31': 'Lakshadweep','32': 'Kerala','33': 'Tamil Nadu','34': 'Puducherry',
  '35': 'Andaman & Nicobar Islands','36': 'Telangana','37': 'Andhra Pradesh (New)','38': 'Ladakh'
};

// ✅ Voucher Type
function getVoucherType(buyer_gstin) {
  if (!buyer_gstin || buyer_gstin.length < 2) return "Purchase";
  const stateCode = buyer_gstin.substring(0, 2);
  const state = GST_STATE_MAP[stateCode];
  if (!state) return "Purchase";
  return `Purchase ${state.split(" ")[0]}`;
}

// ✅ GST SAFE
function safeGST(gstin) {
  if (!gstin || typeof gstin !== "string") return "";
  gstin = gstin.trim();
  return gstin.length >= 2 ? gstin : "";
}

for (const item of items) {

  let raw = item.json.output;

  if (typeof raw === "string") {
    const match = raw.match(/\[\s*{[\s\S]*}\s*\]/);
    raw = match ? match[0] : "";
  }

  if (!raw || raw === "") raw = [];

  const lockedVendor =
    item.json.vendor_name_tally ||
    item.json.vendor?.vendor_name_tally ||
    "";

  if (!raw || (typeof raw === "object" && Object.keys(raw).length === 0)) {
    output.push({
      json: {
        company: "",
        vendor_name_tally: lockedVendor,
        invoice_number: "Invalid",
        invoice_date: "",
        due_date: null,
        seller_gstin: "",
        buyer_gstin: "",
        voucher_type: "Purchase",
        category: "Invalid Invoice",
        product_name: "No readable data (image/scanned PDF)",
        hsn_code: "",
        quantity: 0,
        unit: "",
        rate: 0,
        amount: 0,
        cgst_rate: 0,
        sgst_rate: 0,
        igst_rate: 0,
        cgst_amount: 0,
        sgst_amount: 0,
        igst_amount: 0,
        Invoice_link: item.json.webViewLink || item.json.data?.webViewLink || "",
        GST_AMOUNT: 0,
        status: "failed"
      }
    });
    continue;
  }

  if (typeof raw === "string") {
    try { raw = JSON.parse(raw); } catch { raw = []; }
  }

  if (!Array.isArray(raw)) raw = [raw];

  let ignoreBreakdown = false;

  for (let r of raw) {
    const text = JSON.stringify(r).toLowerCase();
    if (text.includes("details of fees to the above tax invoice")) {
      ignoreBreakdown = true;
      break;
    }
  }

  let hasValidData = false;
  const startIndex = output.length;

  for (let row of raw) {

    if (!row || typeof row !== "object") continue;

    const rowText = JSON.stringify(row).toLowerCase();

    if (
      ignoreBreakdown &&
      (rowText.includes("details of fees") || rowText.includes("tax invoice"))
    ) continue;

    const isTaxRow =
      (rowText.includes("cgst") || rowText.includes("sgst") || rowText.includes("igst")) &&
      (!row.product_name || row.product_name.trim() === "");

    if (isTaxRow) continue;

    if (row.product_name || row.amount || row.rate || row.quantity) {
      hasValidData = true;
    }

    if (!row.product_name && !row.amount && !row.rate && !row.quantity) continue;

    // ✅ FIXED CATEGORY (correct vendor priority)
    let finalCategory = row.category;

    if (
      !finalCategory ||
      finalCategory.toLowerCase() === "refer from category master"
    ) {
      finalCategory = getCategory(
        row.vendor_name_tally || lockedVendor,
        row.product_name
      );
    }

    const sellerGST = safeGST(row.seller_gstin);
    const buyerGST = safeGST(row.buyer_gstin);

    output.push({
      json: {
        company: (row.company || "").trim(),

        // ✅ FIXED VENDOR PASSING
        vendor_name_tally:
          row.vendor_name_tally ||
          lockedVendor ||
          "",

        invoice_number: row.invoice_number || "",
        invoice_date: row.invoice_date || "",
        due_date: row.due_date || null,
        seller_gstin: sellerGST,
        buyer_gstin: buyerGST,
        voucher_type: getVoucherType(buyerGST),

        category: finalCategory,

        product_name: row.product_name || "",
        hsn_code: row.hsn_code || "",
        quantity: Number(row.quantity || 0),
        unit: row.unit || "",
        rate: Number(row.rate || 0),
        amount: Number(row.amount || 0),
        cgst_rate: Number(row.cgst_rate || 0),
        sgst_rate: Number(row.sgst_rate || 0),
        igst_rate: Number(row.igst_rate || 0),
        cgst_amount: Number(row.cgst_amount || 0),
        sgst_amount: Number(row.sgst_amount || 0),
        igst_amount: Number(row.igst_amount || 0),
        Invoice_link: item.json.webViewLink || item.json.data?.webViewLink || "",
        GST_AMOUNT:
          Number(row.cgst_amount || 0) +
          Number(row.sgst_amount || 0) +
          Number(row.igst_amount || 0),
        status: "pending"
      }
    });
  }

  const finalStatus = hasValidData ? "success" : "failed";

  for (let i = startIndex; i < output.length; i++) {
    output[i].json.status = finalStatus;
  }

  if (output.length === startIndex) {
    output.push({
      json: {
        company: "",
        vendor_name_tally: lockedVendor,
        invoice_number: "Invalid",
        invoice_date: "",
        due_date: null,
        seller_gstin: "",
        buyer_gstin: "",
        voucher_type: "Purchase",
        category: "Invalid Invoice",
        product_name: "Unable to read invoice",
        hsn_code: "",
        quantity: 0,
        unit: "",
        rate: 0,
        amount: 0,
        cgst_rate: 0,
        sgst_rate: 0,
        igst_rate: 0,
        cgst_amount: 0,
        sgst_amount: 0,
        igst_amount: 0,
        Invoice_link: item.json.webViewLink || item.json.data?.webViewLink || "",
        GST_AMOUNT: 0,
        status: "failed"
      }
    });
  }

}

return output;

// Get all drive files from Search node
const allFiles = $('Search files and folders').all();

// Get processed IDs from tracker (safe - handles empty sheet)
let processedItems = [];
try {
  processedItems = $('Get row(s) in sheet').all().filter(
    item => item.json && item.json.file_id
  );
} catch(e) {
  processedItems = [];
}

// Build Set of already-processed IDs
const processedIds = new Set(
  processedItems.map(item => item.json.file_id).filter(Boolean)
);

// Filter only NEW files not in tracker
const newFiles = allFiles.filter(item => !processedIds.has(item.json.id));

// If no new files, return empty (IF node will handle this)
if (newFiles.length === 0) {
  return [];
}

// Map and return new files only
return newFiles.map(item => {
  const text = (item.json.name || "").toLowerCase();

  let company = "";
  if (text.includes("amazon")) company = "Amazon Seller Services Private Limited";
  else if (text.includes("flipkart")) company = "Flipkart Internet Private Limited";
  else if (text.includes("swiggy")) company = "Swiggy";
  else if (text.includes("zomato")) company = "Zomato";
  else if (text.includes("blinkit")) company = "Blinkit";
  else {
    const match = item.json.name?.match(
      /([A-Z][A-Za-z &.,]{3,}(Pvt\.?|Private|Limited|Ltd\.?))/i
    );
    if (match) company = match[0];
  }

  return {
    json: {
      ...item.json,
      file_id: item.json.id,
      brand: "KOPARO",
      detected_company: company || "Unknown"
    }
  };
});
